1	// D3/D4: money is integer sen; parsing and the single rounding rule live in billing.ts (pure, imported
2	// directly by graders) and are re-exported here so app code has one money entry point.
3	export { parseRinggitToSen, roundHalfUpDiv } from './billing'
4	
5	// D3: the one place a Prisma BigInt (bigint sen column) becomes a JS number; refuses unsafe values.
6	export function toSen(v: bigint | number): number {
7	  if (typeof v === 'bigint') {
8	    if (v > BigInt(Number.MAX_SAFE_INTEGER) || v < BigInt(Number.MIN_SAFE_INTEGER)) {
9	      throw new Error('Amount is outside the safe integer range')
10	    }
11	    return Number(v)
12	  }
13	  if (!Number.isSafeInteger(v)) throw new Error('Amount must be a safe integer')
14	  return v
15	}
16	
17	// "RM 1,500.00"; built from integer digits (no Intl, so server and browser render identically).
18	export function formatSen(sen: number): string {
19	  const value = toSen(sen)
20	  const abs = Math.abs(value)
21	  const ringgit = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
22	  const cents = String(abs % 100).padStart(2, '0')
23	  return `${value < 0 ? '-' : ''}RM ${ringgit}.${cents}`
24	}
