1	"use client";
2	
3	import { useEffect, useRef, useState, type FormEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import { toast } from "sonner";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Label } from "@/components/ui/label";
9	import {
10	  Select,
11	  SelectContent,
12	  SelectItem,
13	  SelectTrigger,
14	  SelectValue,
15	} from "@/components/ui/select";
16	import { MYT_OFFSET_MS } from "@/lib/billing";
17	import { mytLocalToIso } from "@/lib/dates";
18	import { formatSen, parseRinggitToSen } from "@/lib/money";
19	import { createClient } from "@/lib/supabase/browser";
20	import { callApi } from "./api";
21	
22	const SLIP_BUCKET = "payment-slips";
23	const MAX_SLIP_BYTES = 5 * 1024 * 1024; // R20: at most 5 MB (the bucket enforces the same limit)
24	const SLIP_EXT: Record<string, string> = {
25	  "image/jpeg": "jpg",
26	  "image/png": "png",
27	  "application/pdf": "pdf",
28	};
29	
30	type Method = "cash" | "bank_transfer";
31	const METHOD_ITEMS: { value: Method; label: string }[] = [
32	  { value: "cash", label: "Cash" },
33	  { value: "bank_transfer", label: "Bank transfer" },
34	];
35	
36	type FieldErrors = { amount?: string; receivedAt?: string; slip?: string };
37	
38	// "Now" as a datetime-local value in Malaysia time. Computed on the client only (after mount), by shifting
39	// the instant by the fixed +08:00 offset, so it never depends on the browser's zone (R52).
40	function nowInMytLocal(): string {
41	  return new Date(Date.now() + MYT_OFFSET_MS).toISOString().slice(0, 16);
42	}
43	
44	function validateSlip(file: File | null): string | undefined {
45	  if (!file) return "Attach the bank transfer slip (JPEG, PNG or PDF).";
46	  if (!(file.type in SLIP_EXT)) return "The slip must be a JPEG, PNG or PDF file.";
47	  if (file.size > MAX_SLIP_BYTES) return "The slip must be 5 MB or smaller.";
48	  return undefined;
49	}
50	
51	type Props = { leaseId: string; orgId: string; isManager: boolean };
52	
53	export function RecordPaymentForm({ leaseId, orgId, isManager }: Props) {
54	  const router = useRouter();
55	  const [amount, setAmount] = useState("");
56	  const [method, setMethod] = useState<Method>("cash");
57	  const [receivedAt, setReceivedAt] = useState("");
58	  const [file, setFile] = useState<File | null>(null);
59	  const [errors, setErrors] = useState<FieldErrors>({});
60	  const [submitting, setSubmitting] = useState(false);
61	  const fileRef = useRef<HTMLInputElement>(null);
62	  // D9: one optional Idempotency-Key per form render protects against a double click; a new one after success.
63	  const keyRef = useRef<string | null>(null);
64	
65	  useEffect(() => {
66	    // eslint-disable-next-line react-hooks/set-state-in-effect -- client-only default avoids a hydration mismatch
67	    setReceivedAt(nowInMytLocal());
68	  }, []);
69	
70	  function onAmountChange(value: string) {
71	    setAmount(value);
72	    if (errors.amount) setErrors((e) => ({ ...e, amount: undefined }));
73	  }
74	
75	  function validate(): { amountSen: number; receivedAtIso: string } | null {
76	    const next: FieldErrors = {};
77	    let amountSen = 0;
78	    try {
79	      amountSen = parseRinggitToSen(amount);
80	      if (!Number.isSafeInteger(amountSen)) throw new Error("too large");
81	      if (amountSen <= 0) next.amount = "The amount must be greater than zero.";
82	    } catch {
83	      next.amount = "Enter an amount like 1,500.00";
84	    }
85	    let receivedAtIso = "";
86	    if (!receivedAt) {
87	      next.receivedAt = "Choose when the payment was received (Malaysia time).";
88	    } else {
89	      try {
90	        receivedAtIso = mytLocalToIso(receivedAt);
91	      } catch {
92	        next.receivedAt = "Enter a valid date and time (Malaysia time).";
93	      }
94	    }
95	    if (method === "bank_transfer") {
96	      const slipError = validateSlip(file);
97	      if (slipError) next.slip = slipError;
98	    }
99	    setErrors(next);
100	    return Object.keys(next).length === 0 ? { amountSen, receivedAtIso } : null;
101	  }
102	
103	  async function onSubmit(e: FormEvent<HTMLFormElement>) {
104	    e.preventDefault();
105	    if (submitting) return;
106	    const valid = validate();
107	    if (!valid) return;
108	
109	    setSubmitting(true);
110	    const supabase = createClient();
111	    let slipPath: string | undefined;
112	
113	    if (method === "bank_transfer" && file) {
114	      // R44: path <org_id>/<lease_id>/<uuid>.<ext>; Storage RLS only lets this org's staff upload here.
115	      slipPath = `${orgId}/${leaseId}/${crypto.randomUUID()}.${SLIP_EXT[file.type]}`;
116	      const { error } = await supabase.storage
117	        .from(SLIP_BUCKET)
118	        .upload(slipPath, file, { contentType: file.type, upsert: false });
119	      if (error) {
120	        toast.error(`Slip upload failed: ${error.message}`);
121	        setSubmitting(false);
122	        return;
123	      }
124	    }
125	
126	    keyRef.current ??= crypto.randomUUID();
127	    const res = await callApi<{ id: string; status: string }>(`/api/leases/${leaseId}/payments`, {
128	      method: "POST",
129	      headers: { "Idempotency-Key": keyRef.current },
130	      body: {
131	        amountSen: valid.amountSen,
132	        method,
133	        receivedAt: valid.receivedAtIso,
134	        ...(slipPath ? { slipPath } : {}),
135	      },
136	    });
137	
138	    if (!res.ok) {
139	      toast.error(res.error);
140	      if (slipPath) {
141	        // R20: the server removes the orphan slip itself; this is a best-effort second attempt (the
142	        // browser role has no DELETE policy, so it may be refused, which is fine).
143	        await supabase.storage.from(SLIP_BUCKET).remove([slipPath]).catch(() => undefined);
144	      }
145	      setSubmitting(false);
146	      return;
147	    }
148	
149	    toast.success(
150	      res.data.status === "approved"
151	        ? `Payment of ${formatSen(valid.amountSen)} recorded and approved.`
152	        : `Payment of ${formatSen(valid.amountSen)} recorded. It waits for a manager's approval.`,
153	    );
154	    keyRef.current = null;
155	    setAmount("");
156	    setFile(null);
157	    setErrors({});
158	    if (fileRef.current) fileRef.current.value = "";
159	    setReceivedAt(nowInMytLocal());
160	    setSubmitting(false);
161	    router.refresh();
162	  }
163	
164	  return (
165	    <form onSubmit={onSubmit} noValidate className="grid gap-4 sm:grid-cols-2">
166	      <div className="flex flex-col gap-2">
167	        <Label htmlFor="amount">Amount (RM)</Label>
168	        <Input
169	          id="amount"
170	          inputMode="decimal"
171	          autoComplete="off"
172	          placeholder="1,500.00"
173	          value={amount}
174	          onChange={(e) => onAmountChange(e.target.value)}
175	          aria-invalid={Boolean(errors.amount)}
176	          aria-describedby={errors.amount ? "amount-error" : undefined}
177	          disabled={submitting}
178	        />
179	        {errors.amount && (
180	          <p id="amount-error" className="text-sm text-destructive">
181	            {errors.amount}
182	          </p>
183	        )}
184	      </div>
185	
186	      <div className="flex flex-col gap-2">
187	        <Label htmlFor="method">Method</Label>
188	        <Select
189	          value={method}
190	          items={METHOD_ITEMS}
191	          onValueChange={(v) => {
192	            if (v === "cash" || v === "bank_transfer") {
193	              setMethod(v);
194	              setErrors((e) => ({ ...e, slip: undefined }));
195	            }
196	          }}
197	          disabled={submitting}
198	        >
199	          <SelectTrigger id="method" className="w-full">
200	            <SelectValue />
201	          </SelectTrigger>
202	          <SelectContent>
203	            {METHOD_ITEMS.map((m) => (
204	              <SelectItem key={m.value} value={m.value}>
205	                {m.label}
206	              </SelectItem>
207	            ))}
208	          </SelectContent>
209	        </Select>
210	      </div>
211	
212	      <div className="flex flex-col gap-2">
213	        <Label htmlFor="received-at">Received at (Malaysia time)</Label>
214	        <Input
215	          id="received-at"
216	          type="datetime-local"
217	          value={receivedAt}
218	          onChange={(e) => {
219	            setReceivedAt(e.target.value);
220	            if (errors.receivedAt) setErrors((er) => ({ ...er, receivedAt: undefined }));
221	          }}
222	          aria-invalid={Boolean(errors.receivedAt)}
223	          aria-describedby={errors.receivedAt ? "received-at-error" : undefined}
224	          disabled={submitting}
225	        />
226	        {errors.receivedAt && (
227	          <p id="received-at-error" className="text-sm text-destructive">
228	            {errors.receivedAt}
229	          </p>
230	        )}
231	      </div>
232	
233	      {method === "bank_transfer" && (
234	        <div className="flex flex-col gap-2">
235	          <Label htmlFor="slip">Bank transfer slip (JPEG, PNG or PDF, up to 5 MB)</Label>
236	          <Input
237	            id="slip"
238	            ref={fileRef}
239	            type="file"
240	            accept="image/jpeg,image/png,application/pdf"
241	            onChange={(e) => {
242	              const f = e.target.files?.[0] ?? null;
243	              setFile(f);
244	              setErrors((er) => ({ ...er, slip: f ? validateSlip(f) : undefined }));
245	            }}
246	            aria-invalid={Boolean(errors.slip)}
247	            aria-describedby={errors.slip ? "slip-error" : undefined}
248	            disabled={submitting}
249	          />
250	          {errors.slip && (
251	            <p id="slip-error" className="text-sm text-destructive">
252	              {errors.slip}
253	            </p>
254	          )}
255	        </div>
256	      )}
257	
258	      <div className="flex flex-col gap-2 sm:col-span-2 sm:flex-row sm:items-center sm:justify-between">
259	        <p className="text-sm text-muted-foreground">
260	          {isManager
261	            ? "Payments you record are approved immediately."
262	            : "Payments you record wait for a manager's approval."}
263	        </p>
264	        <Button type="submit" disabled={submitting}>
265	          {submitting ? "Recording..." : "Record payment"}
266	        </Button>
267	      </div>
268	    </form>
269	  );
270	}
