1	"use client";
2	
3	import { useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { toast } from "sonner";
6	import {
7	  AlertDialog,
8	  AlertDialogCancel,
9	  AlertDialogContent,
10	  AlertDialogDescription,
11	  AlertDialogFooter,
12	  AlertDialogHeader,
13	  AlertDialogTitle,
14	} from "@/components/ui/alert-dialog";
15	import { Button } from "@/components/ui/button";
16	import { Label } from "@/components/ui/label";
17	import { Textarea } from "@/components/ui/textarea";
18	import { callApi } from "./api";
19	
20	const MIN_REASON = 5;
21	
22	type Props = {
23	  paymentId: string;
24	  status: "pending_verification" | "approved" | "rejected" | "voided";
25	  amountLabel: string;
26	};
27	
28	// R24: manager-only actions. The buttons are only rendered for managers, but the routes enforce the role
29	// themselves (a hidden button is not a check, R36).
30	export function PaymentActions({ paymentId, status, amountLabel }: Props) {
31	  const router = useRouter();
32	  const [approving, setApproving] = useState(false);
33	
34	  async function approve() {
35	    setApproving(true);
36	    const res = await callApi(`/api/payments/${paymentId}/approve`, { method: "POST" });
37	    setApproving(false);
38	    if (!res.ok) {
39	      toast.error(res.error);
40	      return;
41	    }
42	    toast.success(`Payment of ${amountLabel} approved.`);
43	    router.refresh();
44	  }
45	
46	  if (status === "pending_verification") {
47	    return (
48	      <div className="flex justify-end gap-2">
49	        <Button type="button" size="sm" onClick={approve} disabled={approving}>
50	          {approving ? "Approving..." : "Approve"}
51	        </Button>
52	        <ReasonDialog
53	          paymentId={paymentId}
54	          action="reject"
55	          triggerLabel="Reject"
56	          title="Reject this payment?"
57	          description={`The payment of ${amountLabel} stays on record as rejected and is not allocated to any invoice.`}
58	          confirmLabel="Reject payment"
59	          busyLabel="Rejecting..."
60	          successMessage={`Payment of ${amountLabel} rejected.`}
61	        />
62	      </div>
63	    );
64	  }
65	
66	  if (status === "approved") {
67	    return (
68	      <div className="flex justify-end">
69	        <ReasonDialog
70	          paymentId={paymentId}
71	          action="void"
72	          triggerLabel="Void"
73	          title="Void this payment?"
74	          description={`This releases the allocations of the ${amountLabel} payment, so the invoices it paid become unpaid again. The payment itself is kept on record.`}
75	          confirmLabel="Void payment"
76	          busyLabel="Voiding..."
77	          successMessage={`Payment of ${amountLabel} voided.`}
78	        />
79	      </div>
80	    );
81	  }
82	
83	  return <span className="text-muted-foreground">-</span>;
84	}
85	
86	type ReasonDialogProps = {
87	  paymentId: string;
88	  action: "reject" | "void";
89	  triggerLabel: string;
90	  title: string;
91	  description: string;
92	  confirmLabel: string;
93	  busyLabel: string;
94	  successMessage: string;
95	};
96	
97	function ReasonDialog(p: ReasonDialogProps) {
98	  const router = useRouter();
99	  const [open, setOpen] = useState(false);
100	  const [reason, setReason] = useState("");
101	  const [touched, setTouched] = useState(false);
102	  const [busy, setBusy] = useState(false);
103	
104	  const tooShort = reason.trim().length < MIN_REASON;
105	  const showError = touched && tooShort;
106	  const fieldId = `${p.action}-reason-${p.paymentId}`;
107	
108	  function onOpenChange(next: boolean) {
109	    if (busy) return;
110	    setOpen(next);
111	    if (!next) {
112	      setReason("");
113	      setTouched(false);
114	    }
115	  }
116	
117	  async function confirm() {
118	    setTouched(true);
119	    if (tooShort) return;
120	    setBusy(true);
121	    const res = await callApi(`/api/payments/${p.paymentId}/${p.action}`, {
122	      method: "POST",
123	      body: { reason: reason.trim() },
124	    });
125	    setBusy(false);
126	    if (!res.ok) {
127	      toast.error(res.error);
128	      return;
129	    }
130	    toast.success(p.successMessage);
131	    setOpen(false);
132	    setReason("");
133	    setTouched(false);
134	    router.refresh();
135	  }
136	
137	  return (
138	    <>
139	      <Button type="button" size="sm" variant="destructive" onClick={() => setOpen(true)}>
140	        {p.triggerLabel}
141	      </Button>
142	      <AlertDialog open={open} onOpenChange={onOpenChange}>
143	        <AlertDialogContent>
144	          <AlertDialogHeader>
145	            <AlertDialogTitle>{p.title}</AlertDialogTitle>
146	            <AlertDialogDescription>{p.description}</AlertDialogDescription>
147	          </AlertDialogHeader>
148	          <div className="flex flex-col gap-2">
149	            <Label htmlFor={fieldId}>Reason (at least {MIN_REASON} characters)</Label>
150	            <Textarea
151	              id={fieldId}
152	              value={reason}
153	              onChange={(e) => setReason(e.target.value)}
154	              onBlur={() => setTouched(true)}
155	              aria-invalid={showError}
156	              aria-describedby={showError ? `${fieldId}-error` : undefined}
157	              disabled={busy}
158	              placeholder="Why are you doing this?"
159	            />
160	            {showError && (
161	              <p id={`${fieldId}-error`} className="text-sm text-destructive">
162	                Enter a reason of at least {MIN_REASON} characters.
163	              </p>
164	            )}
165	          </div>
166	          <AlertDialogFooter>
167	            <AlertDialogCancel disabled={busy}>Cancel</AlertDialogCancel>
168	            <Button type="button" variant="destructive" onClick={confirm} disabled={busy}>
169	              {busy ? p.busyLabel : p.confirmLabel}
170	            </Button>
171	          </AlertDialogFooter>
172	        </AlertDialogContent>
173	      </AlertDialog>
174	    </>
175	  );
176	}
