119	      if (error) {
120	        toast.error(`Slip upload failed: ${error.message}`);
121	        setSubmitting(false);
122	        return;
123	      }
124	    }
125	
126	    keyRef.current ??= crypto.randomUUID();
127	    const res = await callApi<{ id: string; status: string }>(`/api/leases/${leaseId}/payments`, {
128	      method: "POST",
129	      headers: { "Idempotency-Key": keyRef.current },
130	      body: {
131	        amountSen: valid.amountSen,
132	        method,
133	        receivedAt: valid.receivedAtIso,
134	        ...(slipPath ? { slipPath } : {}),
135	      },
136	    });
137	
138	    if (!res.ok) {
139	      toast.error(res.error);
