153	    );
154	    keyRef.current = null;
155	    setAmount("");
156	    setFile(null);
157	    setErrors({});
158	    if (fileRef.current) fileRef.current.value = "";
159	    setReceivedAt(nowInMytLocal());
160	    setSubmitting(false);
161	    router.refresh();
162	  }
163	
164	  return (
165	    <form onSubmit={onSubmit} noValidate className="grid gap-4 sm:grid-cols-2">
