67	async function DashboardBody({ userId }: { userId: string }) {
68	  const ctx = { userId };
69	  const now = new Date();
70	  // The current month is the Malaysia calendar month of "now", then five months back.
71	  const currentMonth = toMytDate(now).slice(0, 7);
72	  const [overdue, report] = await Promise.all([
73	    overdueCount(ctx, now),
74	    collectionsReport(ctx, shiftMonth(currentMonth, -(REPORT_MONTHS - 1)), currentMonth),
75	  ]);
76	
77	  const total = report.reduce((sum, r) => sum + r.collectedSen, 0);
78	  const max = report.reduce((m, r) => Math.max(m, r.collectedSen), 0);
79	
80	  return (
81	    <>
82	      <div className="grid gap-4 sm:grid-cols-2">
