88	            </CardTitle>
89	          </CardHeader>
90	          <CardContent className="text-sm text-muted-foreground">
91	            {overdue === 0
92	              ? "Nothing is overdue. Every invoice past its due date is paid."
93	              : "Invoices past their due date (Malaysia time) that are not fully paid."}
94	          </CardContent>
95	        </Card>
96	        <Card>
97	          <CardHeader>
98	            <CardDescription>Collected, last {REPORT_MONTHS} months</CardDescription>
99	            <CardTitle className="text-3xl tabular-nums">{formatSen(total)}</CardTitle>
100	          </CardHeader>
101	          <CardContent className="text-sm text-muted-foreground">
102	            Approved payments, by the month they were received.
103	          </CardContent>
104	        </Card>
105	      </div>
106	
107	      <Card className="mt-6">
108	        <CardHeader>
109	          <CardTitle>Collections by month</CardTitle>
110	          <CardDescription>
111	            {monthLabel(report[0]?.month ?? currentMonth)} to {monthLabel(currentMonth)}, approved payments only.
112	          </CardDescription>
113	        </CardHeader>
114	        <CardContent>
115	          {total === 0 ? (
116	            <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
117	              No approved payments in these months yet. Record a payment on a lease to see it here.
118	            </p>
119	          ) : null}
120	          <Table className={total === 0 ? "mt-4" : undefined}>
121	            <TableHeader>
122	              <TableRow>
123	                <TableHead>Month</TableHead>
124	                <TableHead className="w-1/2">Collected</TableHead>
125	                <TableHead className="text-right">Amount</TableHead>
126	              </TableRow>
127	            </TableHeader>
128	            <TableBody>
129	              {report.map((r) => (
130	                <TableRow key={r.month}>
131	                  <TableCell className="font-medium">
132	                    {monthLabel(r.month)}
133	                    {r.month === currentMonth && (
134	                      <Badge variant="outline" className="ml-2">
135	                        This month
136	                      </Badge>
137	                    )}
138	                  </TableCell>
139	                  <TableCell>
140	                    <div className="h-2 w-full rounded-full bg-muted" aria-hidden="true">
141	                      <div
142	                        className="h-2 rounded-full bg-primary"
143	                        style={{ width: max === 0 ? "0%" : `${Math.round((r.collectedSen / max) * 100)}%` }}
144	                      />
145	                    </div>
146	                  </TableCell>
147	                  <TableCell className="text-right tabular-nums">{formatSen(r.collectedSen)}</TableCell>
148	                </TableRow>
149	              ))}
150	            </TableBody>
151	          </Table>
152	        </CardContent>
153	      </Card>
154	    </>
155	  );
156	}
