7	
8	// R44: the slip is never read from Storage by the browser; the server signs a 60 s URL from the DB row.
9	export function ViewSlipButton({ paymentId }: { paymentId: string }) {
10	  const [loading, setLoading] = useState(false);
11	
12	  async function open() {
13	    setLoading(true);
14	    // Open the tab synchronously (inside the click) so popup blockers allow it, then point it at the URL.
15	    const tab = window.open("about:blank", "_blank");
16	    if (tab) tab.opener = null;
17	    const res = await callApi<{ url?: unknown }>(`/api/payments/${paymentId}/slip`, { method: "GET" });
18	    setLoading(false);
19	    if (!res.ok) {
20	      tab?.close();
21	      toast.error(res.error);
22	      return;
23	    }
24	    const url = res.data.url;
25	    if (typeof url !== "string" || url.length === 0) {
26	      tab?.close();
27	      toast.error("The server did not return a slip link.");
28	      return;
29	    }
30	    if (tab) {
31	      tab.location.href = url;
32	    } else {
33	      toast.info("Your browser blocked the new tab.", {
34	        action: { label: "Open slip", onClick: () => window.open(url, "_blank", "noopener") },
35	      });
36	    }
37	  }
38	
39	  return (
40	    <Button type="button" variant="outline" size="sm" onClick={open} disabled={loading}>
41	      {loading ? "Opening..." : "View slip"}
42	    </Button>
43	  );
44	}
