31	  end_date: z.string(),
32	  monthly_rent_sen: sen,
33	  deposit_sen: sen,
34	});
35	const unitRow = z.object({ id: z.string(), name: z.string() });
36	const invoiceRow = z.object({
37	  id: z.string(),
38	  lease_id: z.string(),
