19	// Money columns are bigint in Postgres; PostgREST sends them as JSON numbers, validated as safe integers here.
20	const sen = z.number().int().safe();
21	const tenantRow = z.object({
22	  id: z.string(),
23	  full_name: z.string(),
24	  email: z.string(),
25	  phone: z.string().nullable(),
26	});
27	const leaseRow = z.object({
28	  id: z.string(),
29	  unit_id: z.string(),
30	  start_date: z.string(),
31	  end_date: z.string(),
32	  monthly_rent_sen: sen,
33	  deposit_sen: sen,
34	});
35	const unitRow = z.object({ id: z.string(), name: z.string() });
36	const invoiceRow = z.object({
37	  id: z.string(),
38	  lease_id: z.string(),
39	  kind: z.enum(["deposit", "rent"]),
40	  period_index: z.number().int().nullable(),
41	  period_start: z.string().nullable(),
42	  period_end: z.string().nullable(),
43	  due_date: z.string(),
44	  amount_sen: sen,
45	});
46	const allocationRow = z.object({ invoice_id: z.string(), amount_sen: sen });
47	const paymentRow = z.object({
48	  id: z.string(),
49	  lease_id: z.string(),
50	  amount_sen: sen,
51	  unapplied_sen: sen,
52	  method: z.enum(["cash", "bank_transfer", "online"]),
53	  status: z.enum(["pending_verification", "approved", "rejected", "voided"]),
54	  received_at: z.string(),
55	});
56	
57	type Tenant = z.infer<typeof tenantRow>;
58	type Data = {
59	  tenants: Tenant[];
60	  leases: LeaseView[];
61	  invoices: InvoiceView[];
62	  payments: PaymentView[];
63	  paidByInvoice: Map<string, number>;
64	};
65	
66	async function loadData(): Promise<Data> {
67	  const supabase = createClient();
68	  // RLS (R42) limits every table to the signed-in tenant's own rows; no filter is needed or trusted here.
69	  const [tenants, leases, units, invoices, allocations, payments] = await Promise.all([
70	    supabase.from("tenants").select("id, full_name, email, phone").order("full_name"),
71	    supabase
72	      .from("leases")
73	      .select("id, unit_id, start_date, end_date, monthly_rent_sen, deposit_sen")
74	      .order("start_date", { ascending: false }),
75	    supabase.from("units").select("id, name"),
76	    supabase
77	      .from("invoices")
78	      .select("id, lease_id, kind, period_index, period_start, period_end, due_date, amount_sen")
79	      .order("due_date")
80	      .order("period_index", { nullsFirst: true }),
81	    supabase.from("payment_allocations").select("invoice_id, amount_sen"),
82	    supabase
83	      .from("payments")
84	      .select("id, lease_id, amount_sen, unapplied_sen, method, status, received_at")
85	      .order("received_at", { ascending: false }),
86	  ]);
87	  for (const r of [tenants, leases, units, invoices, allocations, payments]) {
88	    if (r.error) throw new Error(r.error.message);
89	  }
90	  const unitName = new Map(z.array(unitRow).parse(units.data).map((u) => [u.id, u.name]));
91	  const paidByInvoice = new Map<string, number>();
92	  for (const a of z.array(allocationRow).parse(allocations.data)) {
93	    paidByInvoice.set(a.invoice_id, (paidByInvoice.get(a.invoice_id) ?? 0) + a.amount_sen);
94	  }
95	  return {
96	    tenants: z.array(tenantRow).parse(tenants.data),
97	    leases: z.array(leaseRow).parse(leases.data).map((l) => ({
98	      id: l.id,
99	      unitName: unitName.get(l.unit_id) ?? "-",
100	      startDate: l.start_date,
101	      endDate: l.end_date,
102	      monthlyRentSen: l.monthly_rent_sen,
103	      depositSen: l.deposit_sen,
104	    })),
105	    invoices: z.array(invoiceRow).parse(invoices.data).map((i) => ({
106	      id: i.id,
107	      leaseId: i.lease_id,
108	      kind: i.kind,
109	      periodIndex: i.period_index,
110	      periodStart: i.period_start,
111	      periodEnd: i.period_end,
112	      dueDate: i.due_date,
113	      amountSen: i.amount_sen,
114	    })),
115	    payments: z.array(paymentRow).parse(payments.data).map((p) => ({
116	      id: p.id,
117	      leaseId: p.lease_id,
118	      amountSen: p.amount_sen,
119	      unappliedSen: p.unapplied_sen,
120	      method: p.method,
121	      status: p.status,
122	      receivedAt: p.received_at,
123	    })),
124	    paidByInvoice,
125	  };
126	}
