271	function isCreatedBill(v: unknown): v is CreatedBill {
272	  if (typeof v !== "object" || v === null) return false;
273	  const o = v as Record<string, unknown>;
274	  return typeof o.billId === "string" && typeof o.amountSen === "number" && Number.isSafeInteger(o.amountSen);
275	}
276	
277	function errorMessage(v: unknown): string | null {
278	  if (typeof v !== "object" || v === null) return null;
279	  const e = (v as Record<string, unknown>).error;
280	  return typeof e === "string" ? e : null;
281	}
