10	// Same shape as the tenants.phone CHECK: optional +, a digit, then 5-19 digits, spaces or dashes (6-20 chars).
11	const PHONE_RE = /^\+?[0-9][0-9 -]{5,19}$/;
12	
13	export function PhoneForm({
14	  tenantId,
15	  phone,
16	  onSaved,
17	}: {
18	  tenantId: string;
19	  phone: string | null;
20	  onSaved: (phone: string) => void;
21	}) {
22	  const [value, setValue] = useState(phone ?? "");
23	  const [saving, setSaving] = useState(false);
24	  const [invalid, setInvalid] = useState<string | null>(null);
25	
26	  async function onSubmit(e: FormEvent<HTMLFormElement>) {
27	    e.preventDefault();
28	    const next = value.trim();
29	    if (!PHONE_RE.test(next)) {
30	      setInvalid("Use digits, spaces or dashes with an optional leading +, 6 to 20 characters.");
31	      return;
32	    }
33	    setInvalid(null);
34	    setSaving(true);
35	    // R42: the browser writes straight to PostgREST; RLS and the column grant allow only the own row's phone.
36	    const { data, error } = await createClient().from("tenants").update({ phone: next }).eq("id", tenantId).select();
37	    setSaving(false);
38	    if (error) {
39	      toast.error(error.message);
40	      return;
41	    }
42	    if (!data || data.length === 0) {
43	      toast.error("Your phone number was not updated");
44	      return;
45	    }
46	    setValue(next);
47	    onSaved(next);
48	    toast.success("Phone number updated");
49	  }
50	
51	  return (
52	    <form onSubmit={onSubmit} className="flex flex-col gap-2" noValidate>
53	      <Label htmlFor={`phone-${tenantId}`}>Phone number</Label>
54	      <div className="flex flex-wrap gap-2">
55	        <Input
56	          id={`phone-${tenantId}`}
57	          name="phone"
58	          type="tel"
59	          autoComplete="tel"
60	          className="max-w-xs"
61	          value={value}
62	          onChange={(e) => setValue(e.target.value)}
63	          disabled={saving}
64	          aria-invalid={invalid !== null}
65	          aria-describedby={invalid ? `phone-error-${tenantId}` : undefined}
66	        />
67	        <Button type="submit" disabled={saving}>
68	          {saving ? "Saving..." : "Save"}
69	        </Button>
70	      </div>
71	      {invalid && (
72	        <p id={`phone-error-${tenantId}`} className="text-sm text-destructive">
73	          {invalid}
74	        </p>
75	      )}
76	    </form>
77	  );
78	}
